local VERSION = "1.0.0" local TITLE = "Anime Girl Card Collection" local FILE_NAME = "AGCC_Hub_Config.json" local genv = (type(getgenv) == "function" and getgenv()) or _G if type(genv.AGCC_HUB_UNLOAD) == "function" then pcall(genv.AGCC_HUB_UNLOAD) end local Players = game:GetService("Players") local RunService = game:GetService("RunService") local UserInputService = game:GetService("UserInputService") local TweenService = game:GetService("TweenService") local HttpService = game:GetService("HttpService") local StarterGui = game:GetService("StarterGui") local VirtualUser = game:GetService("VirtualUser") local LocalPlayer = Players.LocalPlayer local function typeofFn(v) return type(v) == "function" end local function identify() local ok, name = pcall(function() if typeofFn(identifyexecutor) then return identifyexecutor() end if typeofFn(get_executor_name) then return get_executor_name() end return "unknown" end) return ok and tostring(name) or "unknown" end local CAP = { fireproximityprompt = typeofFn(fireproximityprompt), getconnections = typeofFn(getconnections), firesignal = typeofFn(firesignal), writefile = typeofFn(writefile), readfile = typeofFn(readfile), isfile = typeofFn(isfile), setclipboard = typeofFn(setclipboard), gethui = typeofFn(gethui), } local State = { running = true, config = {}, bindings = {}, features = {}, plotPath = nil, plotConfirmed = false, plazaCFrame = nil, baseCFrame = nil, roll = { active = false, tracker = nil, baseline = "", started = 0, changes = 0, lastResult = "", stoppedReason = "" }, upgrade = { active = false, tracker = nil, clicks = 0 }, logs = {}, espObjects = {}, rewardCooldown = {}, combat = { raid = { actions = 0, lastAction = 0 }, tower = { actions = 0, lastAction = 0 } }, } local Defaults = { rgb = true, quickbar = false, menuScale = 1, antiAfk = false, espPrompts = false, espLimited = false, espDistance = 250, autoSell = false, autoCarry = false, warpToSell = false, requireOwnPlot = true, sellInterval = 3, farmMaxActions = 300, autoEquip = false, equipInterval = 12, autoUpgrade = false, upgradeInterval = 5, upgradeCurrency = "gems", upgradeCap = 0, upgradeReserve = 0, upgradeMaxClicks = 50, rewardFree = false, rewardDaily = false, rewardPlaytime = false, rewardOffline = false, rewardInterval = 8, rewardCooldown = 60, rewardMaxClaims = 100, raidEnabled = false, towerEnabled = false, combatInterval = 4, combatMaxActions = 200, combatTimeout = 120, rollEnabled = false, rollCurrency = "gems", rollCapGems = 0, rollReserveGems = 0, rollCapCash = 0, rollReserveCash = 0, rollMaxRolls = 200, rollMaxSeconds = 600, rollPoll = 0.35, rollStopOnTarget = true, rollStartToggles = false, rollAutoOpen = true, rollGradeTarget = "", rollTraitTarget = "", } for k, v in pairs(Defaults) do State.config[k] = v end local Connections = {} local function connect(signal, fn) local c = signal:Connect(fn) table.insert(Connections, c) return c end local function log(msg) local line = os.date("!%H:%M:%S") .. " " .. tostring(msg) table.insert(State.logs, 1, line) if #State.logs > 90 then table.remove(State.logs) end if State.refreshLogs then State.refreshLogs() end end local function safe(fn, ...) local ok, a, b = pcall(fn, ...) if not ok then log("ERROR: " .. tostring(a)) end return ok, a, b end local function norm(s) s = tostring(s or ""):lower() s = s:gsub("[%s%p]+", "") return s end local function trim(s) return (tostring(s or ""):gsub("^%s+", ""):gsub("%s+$", "")) end local function textOf(inst) if not inst then return "" end local ok, v = pcall(function() if inst:IsA("TextLabel") or inst:IsA("TextButton") or inst:IsA("TextBox") then return inst.Text end if inst:IsA("StringValue") then return inst.Value end return inst.Name end) return ok and tostring(v or "") or inst.Name end local function instancePath(inst) if not inst then return "" end local ok, p = pcall(function() return inst:GetFullName() end) return ok and p or inst.Name end local function resolvePath(path) if not path or path == "" then return nil end local obj = game for part in string.gmatch(path, "[^.]+") do if part == "game" then obj = game else obj = obj:FindFirstChild(part) end if not obj then return nil end end return obj end local function guiVisible(inst) if not inst then return false end local ok, v = pcall(function() local cur = inst while cur and cur ~= game do if cur:IsA("ScreenGui") then if not cur.Enabled then return false end elseif cur:IsA("GuiObject") then if not cur.Visible then return false end end cur = cur.Parent end return true end) return ok and v end local function buttonInteractable(btn) if not btn or not btn:IsA("GuiButton") then return false end if not guiVisible(btn) then return false end local ok, v = pcall(function() return btn.Interactable end) if ok and v == false then return false end return true end local function parseNumber(text) text = tostring(text or ""):gsub(",", "") local num, suffix = text:match("(-?%d+%.?%d*)%s*([KkMmBbTt]?)") if not num then return nil end local n = tonumber(num) if not n then return nil end suffix = suffix:lower() if suffix == "k" then n = n * 1e3 elseif suffix == "m" then n = n * 1e6 elseif suffix == "b" then n = n * 1e9 elseif suffix == "t" then n = n * 1e12 end return n end local function fmt(n) if n == nil then return "?" end if n >= 1e9 then return string.format("%.2fB", n / 1e9) end if n >= 1e6 then return string.format("%.2fM", n / 1e6) end if n >= 1e3 then return string.format("%.1fK", n / 1e3) end return tostring(math.floor(n)) end local function newTracker() return { lastGems = nil, lastCash = nil, spentGems = 0, spentCash = 0, decreases = 0 } end local function trackerUpdate(tr, gems, cash) if not tr then return end if gems ~= nil then if tr.lastGems ~= nil and gems < tr.lastGems then tr.spentGems += tr.lastGems - gems tr.decreases += 1 end tr.lastGems = gems end if cash ~= nil then if tr.lastCash ~= nil and cash < tr.lastCash then tr.spentCash += tr.lastCash - cash tr.decreases += 1 end tr.lastCash = cash end end local function getCurrency() local g = resolvePath(State.bindings.gemsLabel and State.bindings.gemsLabel.path) local c = resolvePath(State.bindings.cashLabel and State.bindings.cashLabel.path) local gems = g and parseNumber(textOf(g)) or nil local cash = c and parseNumber(textOf(c)) or nil return gems, cash end local function getRoot() local ok, h = pcall(function() if CAP.gethui then return gethui() end return game:GetService("CoreGui") end) if ok and h then return h end return LocalPlayer:WaitForChild("PlayerGui") end local RootGui = Instance.new("ScreenGui") RootGui.Name = "AGCC_Hub" RootGui.ResetOnSpawn = false RootGui.IgnoreGuiInset = true RootGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling RootGui.DisplayOrder = 999 RootGui.Parent = getRoot() local function isOurGui(inst) return inst and (inst == RootGui or inst:IsDescendantOf(RootGui)) end local function make(class, props, parent) local obj = Instance.new(class) for k, v in pairs(props or {}) do obj[k] = v end if parent then obj.Parent = parent end return obj end local function corner(obj, r) make("UICorner", { CornerRadius = UDim.new(0, r or 8) }, obj) end local function stroke(obj, color, thick, trans) return make("UIStroke", { Color = color or Color3.fromRGB(255, 40, 70), Thickness = thick or 1, Transparency = trans or 0, ApplyStrokeMode = Enum.ApplyStrokeMode.Border }, obj) end local function padding(obj, p) make("UIPadding", { PaddingTop = UDim.new(0, p), PaddingBottom = UDim.new(0, p), PaddingLeft = UDim.new(0, p), PaddingRight = UDim.new(0, p) }, obj) end local function list(obj, gap) local l = make("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, gap or 8) }, obj) return l end local COLORS = { bg = Color3.fromRGB(8, 8, 12), panel = Color3.fromRGB(16, 16, 22), card = Color3.fromRGB(22, 22, 30), red = Color3.fromRGB(255, 40, 70), redDark = Color3.fromRGB(120, 15, 35), text = Color3.fromRGB(240, 240, 245), muted = Color3.fromRGB(160, 160, 175), green = Color3.fromRGB(60, 220, 130), yellow = Color3.fromRGB(255, 200, 60), } local FONT = Enum.Font.SourceSansBold local FONT_LIGHT = Enum.Font.SourceSans local Toast = make("TextLabel", { Size = UDim2.new(0.8, 0, 0, 42), Position = UDim2.new(0.1, 0, 0, 14), BackgroundColor3 = COLORS.panel, TextColor3 = COLORS.text, Font = FONT, TextSize = 16, Text = "", TextWrapped = true, Visible = false, ZIndex = 100, BorderSizePixel = 0, }, RootGui) corner(Toast, 10); stroke(Toast, COLORS.red, 1) local toastToken = 0 local function notify(msg) toastToken += 1 local token = toastToken Toast.Text = tostring(msg) Toast.Visible = true Toast.TextTransparency = 0 task.delay(3, function() if token == toastToken and RootGui.Parent then TweenService:Create(Toast, TweenInfo.new(0.35), { TextTransparency = 1, BackgroundTransparency = 1 }):Play() task.delay(0.4, function() if token == toastToken then Toast.Visible = false; Toast.BackgroundTransparency = 0 end end) end end) end local function clickButton(btn) if not buttonInteractable(btn) then return false, "ปุ่มมองไม่เห็นหรือกดไม่ได้" end if isOurGui(btn) then return false, "ห้ามกดปุ่มของฮับเอง" end local fired = false if CAP.getconnections then local ok, con = pcall(getconnections, btn.MouseButton1Click) if ok and type(con) == "table" and #con > 0 then for _, c in ipairs(con) do pcall(function() c:Fire() end) end fired = true else local ok2, act = pcall(getconnections, btn.Activated) if ok2 and type(act) == "table" and #act > 0 then for _, c in ipairs(act) do pcall(function() c:Fire() end) end fired = true end end elseif CAP.firesignal then fired = pcall(firesignal, btn.MouseButton1Click) if not fired then fired = pcall(firesignal, btn.Activated) end end if not fired then return false, "executor ไม่มี getconnections/firesignal ที่ใช้ได้" end return true, "ส่งคำสั่งกดแล้ว" end local function pressBinding(key) local b = State.bindings[key] local inst = b and resolvePath(b.path) if not inst then return false, "ยังไม่ได้ผูก: " .. key end return clickButton(inst) end local function characterRoot() local char = LocalPlayer.Character return char and char:FindFirstChild("HumanoidRootPart") end local function promptPart(prompt) local parent = prompt and prompt.Parent if not parent then return nil end if parent:IsA("BasePart") then return parent end return parent:FindFirstChildWhichIsA("BasePart", true) or parent:FindFirstAncestorWhichIsA("BasePart") end local function promptDistance(prompt) local root = characterRoot() local part = promptPart(prompt) if not root or not part then return math.huge end return (root.Position - part.Position).Magnitude end local function firePrompt(prompt, allowWarp) if not CAP.fireproximityprompt then return false, "executor ไม่มี fireproximityprompt" end if not prompt or not prompt.Parent or not prompt.Enabled then return false, "พรอมต์ไม่พร้อม" end local dist = promptDistance(prompt) local maxDist = prompt.MaxActivationDistance or 10 if dist > maxDist then if allowWarp then local root = characterRoot() local part = promptPart(prompt) if root and part then root.CFrame = part.CFrame + Vector3.new(0, 4, 0) end task.wait(0.15) dist = promptDistance(prompt) end if dist > maxDist then return false, "อยู่ไกลจากพรอมต์เกินไป" end end local ok, err = pcall(fireproximityprompt, prompt) if not ok then return false, tostring(err) end return true, "ยิงพรอมต์แล้ว" end local function scanGui(predicate, limit) local out = {} local pg = LocalPlayer:FindFirstChild("PlayerGui") if not pg then return out end local ok, desc = pcall(function() return pg:GetDescendants() end) if not ok then return out end for _, inst in ipairs(desc) do if not isOurGui(inst) and predicate(inst) then table.insert(out, inst) if #out >= (limit or 400) then break end end end return out end local function scanPrompts(limit) local out = {} local ok, desc = pcall(function() return workspace:GetDescendants() end) if not ok then return out end for _, inst in ipairs(desc) do if inst:IsA("ProximityPrompt") then table.insert(out, inst) if #out >= (limit or 250) then break end end end return out end local function bind(key, inst, kind) if not inst then State.bindings[key] = nil; return end State.bindings[key] = { path = instancePath(inst), label = textOf(inst), kind = kind or inst.ClassName } end local function getBind(key) local b = State.bindings[key] return b and resolvePath(b.path) or nil end local BindingSpecs = { { key = "rollOpen", name = "ปุ่มเปิด Auto Roll", kind = "button" }, { key = "rollPanel", name = "พาเนล SettingsAuto", kind = "container" }, { key = "rollStart", name = "ปุ่ม Start โรล", kind = "button" }, { key = "rollStop", name = "ปุ่ม Stop โรล", kind = "button" }, { key = "gradeList", name = "ลิสต์เกรด", kind = "container" }, { key = "traitList", name = "ลิสต์ Trait", kind = "container" }, { key = "gradeResult", name = "ข้อความผลเกรด", kind = "label" }, { key = "traitResult", name = "ข้อความผล trait", kind = "label" }, { key = "gemsLabel", name = "ตัวเลข Gems", kind = "label" }, { key = "cashLabel", name = "ตัวเลข Cash", kind = "label" }, { key = "currencyGems", name = "ตัวเลือก Use Gems", kind = "button" }, { key = "currencyCash", name = "ตัวเลือก Use Cash", kind = "button" }, { key = "currencyGemsFirst", name = "ตัวเลือก Gems First", kind = "button" }, { key = "equipBest", name = "ปุ่ม EQUIPEBEST", kind = "button" }, { key = "upgradeButton", name = "ปุ่มอัปเกรด", kind = "button" }, { key = "upgradeCurrencyLabel", name = "ตัวเลขเงินตอนอัปเกรด", kind = "label" }, { key = "rewardOpen", name = "ปุ่มเปิดหน้ารางวัล", kind = "button" }, { key = "sellPrompt", name = "พรอมต์ Sell Card Boxes", kind = "prompt" }, { key = "carryPrompt", name = "พรอมต์ Carry", kind = "prompt" }, { key = "raidOpen", name = "ปุ่มเปิด Boss Raid", kind = "button" }, { key = "raidStart", name = "ปุ่มเริ่ม Boss Raid", kind = "button" }, { key = "raidNext", name = "ปุ่มถัดไป Boss Raid", kind = "button" }, { key = "raidFight", name = "พรอมต์ Fight บอส", kind = "prompt" }, { key = "towerOpen", name = "ปุ่มเปิด Infinity Tower", kind = "button" }, { key = "towerStart", name = "ปุ่มเริ่ม Tower", kind = "button" }, { key = "towerNext", name = "ปุ่มถัดไป Tower", kind = "button" }, } local function autoBind() local found = 0 local buttons = scanGui(function(i) return i:IsA("GuiButton") end, 800) local containers = scanGui(function(i) return i:IsA("GuiObject") and (i.Name:lower():find("settingsauto") or i.Name:lower():find("autoroll")) end, 50) for _, c in ipairs(containers) do if not State.bindings.rollPanel then bind("rollPanel", c, "container"); found += 1 end end for _, b in ipairs(buttons) do local t = norm(textOf(b)) if not State.bindings.equipBest and (t == "equipebest" or t == "equipbest") then bind("equipBest", b, "button"); found += 1 end end for _, p in ipairs(scanPrompts(400)) do local t = norm(p.ActionText .. " " .. p.ObjectText .. " " .. p.Name) if not State.bindings.sellPrompt and t:find("sellcardboxes", 1, true) then bind("sellPrompt", p, "prompt"); found += 1 end if not State.bindings.carryPrompt and t:find("carry", 1, true) then bind("carryPrompt", p, "prompt"); found += 1 end if not State.bindings.raidFight and t:find("fight", 1, true) then bind("raidFight", p, "prompt"); found += 1 end end log("Auto-bind พบ " .. found .. " รายการ (ตรวจความถูกต้องก่อนใช้)") notify("Auto-bind พบ " .. found .. " รายการ") return found end local function getPlots() local out = {} local plots = workspace:FindFirstChild("Plots") if not plots then return out end local ok, desc = pcall(function() return plots:GetDescendants() end) if not ok then return out end for _, inst in ipairs(desc) do if inst:IsA("Model") or inst:IsA("Folder") then local n = inst.Name:lower() if n:find("plot") or tonumber(inst.Name) then table.insert(out, inst) end end if #out >= 120 then break end end return out end local function detectOwnPlot() for _, plot in ipairs(getPlots()) do local ok, owner = pcall(function() for _, attr in ipairs({ "OwnerUserId", "UserId", "Owner", "Player", "OwnerName" }) do local v = plot:GetAttribute(attr) if v ~= nil then if tonumber(v) == LocalPlayer.UserId then return true end if tostring(v) == LocalPlayer.Name or tostring(v) == LocalPlayer.DisplayName then return true end if typeof(v) == "Instance" and v == LocalPlayer then return true end end end for _, child in ipairs(plot:GetChildren()) do if child:IsA("ObjectValue") and child.Value == LocalPlayer then return true end if child:IsA("StringValue") and (child.Value == LocalPlayer.Name or child.Value == LocalPlayer.DisplayName) then return true end if child:IsA("IntValue") and child.Value == LocalPlayer.UserId then return true end end end) if ok and owner then State.plotPath = instancePath(plot) State.plotConfirmed = true log("พบพล็อตจาก owner: " .. State.plotPath) return plot end end return nil end local function getOwnPlot() if not State.plotConfirmed then return nil end return resolvePath(State.plotPath) end local function findPromptUnder(root, keywords) if not root then return nil end local ok, desc = pcall(function() return root:GetDescendants() end) if not ok then return nil end for _, inst in ipairs(desc) do if inst:IsA("ProximityPrompt") then local t = norm(inst.ActionText .. " " .. inst.ObjectText .. " " .. inst.Name) for _, kw in ipairs(keywords) do if t:find(norm(kw), 1, true) then return inst end end end end return nil end local function teleportTo(cf) local root = characterRoot() if not root then return false, "ไม่พบตัวละคร" end root.CFrame = cf return true, "วาปแล้ว" end local function saveConfig() if not CAP.writefile then return false, "executor ไม่มี writefile" end local savedConfig = {} for k, v in pairs(State.config) do savedConfig[k] = v end for _, k in ipairs({ "rollEnabled", "autoSell", "autoCarry", "autoEquip", "autoUpgrade", "rewardFree", "rewardDaily", "rewardPlaytime", "rewardOffline", "raidEnabled", "towerEnabled", "antiAfk", "espPrompts", "espLimited" }) do savedConfig[k] = false end local data = { version = VERSION, config = savedConfig, bindings = State.bindings, plotPath = State.plotPath, plazaCFrame = State.plazaCFrame and { State.plazaCFrame:GetComponents() }, baseCFrame = State.baseCFrame and { State.baseCFrame:GetComponents() }, } local ok, err = pcall(function() writefile(FILE_NAME, HttpService:JSONEncode(data)) end) if ok then log("บันทึกค่าแล้ว"); return true end return false, tostring(err) end local function loadConfig() if not CAP.readfile or not CAP.isfile then return false, "executor ไม่มี readfile/isfile" end local ok, exists = pcall(isfile, FILE_NAME) if not ok or not exists then return false, "ไม่พบไฟล์บันทึก" end local ok2, data = pcall(function() return HttpService:JSONDecode(readfile(FILE_NAME)) end) if not ok2 or type(data) ~= "table" then return false, "ไฟล์บันทึกเสียหาย" end if type(data.config) == "table" then for k, v in pairs(data.config) do if Defaults[k] ~= nil then State.config[k] = v end end end for _, k in ipairs({ "rollEnabled", "autoSell", "autoCarry", "autoEquip", "autoUpgrade", "rewardFree", "rewardDaily", "rewardPlaytime", "rewardOffline", "raidEnabled", "towerEnabled", "antiAfk", "espPrompts", "espLimited" }) do State.config[k] = false end if type(data.bindings) == "table" then State.bindings = data.bindings end State.plotPath = data.plotPath State.plotConfirmed = false if type(data.plazaCFrame) == "table" then State.plazaCFrame = CFrame.new(table.unpack(data.plazaCFrame)) end if type(data.baseCFrame) == "table" then State.baseCFrame = CFrame.new(table.unpack(data.baseCFrame)) end log("โหลดค่าแล้ว (ระบบอัตโนมัติยังปิดทั้งหมด)") return true end local function featureEnabled(key) return State.config[key] == true end local stopRolling local function setFeature(key, value, reason) State.config[key] = value and true or false if State.syncFeature then State.syncFeature(key) end if reason then log((value and "เปิด: " or "ปิด: ") .. key .. " (" .. reason .. ")") end end local function stopAll(reason) for _, key in ipairs({ "autoSell", "autoCarry", "autoEquip", "autoUpgrade", "rewardFree", "rewardDaily", "rewardPlaytime", "rewardOffline", "raidE