nChange, nv); if not ok then State.config[key] = not nv; log("toggle error: " .. tostring(err)) end end sync() end) table.insert(syncWidgets, sync); sync() return f, sync end local function button(parent, text, fn, color) local b = make("TextButton", { Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = color or COLORS.redDark, Text = text, TextColor3 = COLORS.text, Font = FONT, TextSize = 14, BorderSizePixel = 0, ZIndex = 15 }, parent) corner(b, 8) b.MouseButton1Click:Connect(function() safe(fn) end) return b end local function numberInput(parent, key, title, minV, maxV, step) local f = card(parent, title, "") local row = make("Frame", { Size = UDim2.new(1, 0, 0, 32), BackgroundTransparency = 1, ZIndex = 15 }, f) local box = make("TextBox", { Size = UDim2.new(1, -100, 1, 0), BackgroundColor3 = COLORS.panel, Text = tostring(State.config[key]), TextColor3 = COLORS.text, Font = FONT, TextSize = 15, ClearTextOnFocus = false, BorderSizePixel = 0, ZIndex = 16 }, row) corner(box, 6) local apply = make("TextButton", { Size = UDim2.fromOffset(90, 30), Position = UDim2.new(1, -90, 0, 1), BackgroundColor3 = COLORS.redDark, Text = "ตั้งค่า", TextColor3 = COLORS.text, Font = FONT, TextSize = 14, BorderSizePixel = 0, ZIndex = 16 }, row) corner(apply, 6) apply.MouseButton1Click:Connect(function() local n = tonumber(box.Text) if not n then notify("กรอกตัวเลข"); return end n = math.clamp(n, minV or 0, maxV or 1e12) if step then n = math.floor(n / step + 0.5) * step end State.config[key] = n box.Text = tostring(n) notify("ตั้ง " .. title .. " = " .. tostring(n)) end) table.insert(syncWidgets, function() box.Text = tostring(State.config[key]) end) return f end local function dropdown(parent, title, getOptions, getter, setter) local f = card(parent, title, "") local btn = make("TextButton", { Size = UDim2.new(1, 0, 0, 34), BackgroundColor3 = COLORS.panel, Text = tostring(getter() or "เลือก"), TextColor3 = COLORS.text, Font = FONT, TextSize = 14, BorderSizePixel = 0, ZIndex = 15 }, f) co