t(items, { inst = inst, text = (t ~= "" and t or inst.Name) .. " | " .. inst.ClassName .. " | " .. instancePath(inst) }) end end bindInfo.Text = "พบ " .. #items .. " รายการสำหรับ " .. spec.name .. " (แสดงสูงสุด 120)" for i = 1, math.min(#items, 120) do local it = items[i] local b = make("TextButton", { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = COLORS.panel, Text = it.text, TextColor3 = COLORS.text, Font = FONT_LIGHT, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, BorderSizePixel = 0, ZIndex = 15 }, bindList) corner(b, 6); padding(b, 6) b.MouseButton1Click:Connect(function() bind(spec.key, it.inst, spec.kind) notify("ผูก " .. spec.name .. " แล้ว") log("ผูก " .. spec.key .. " -> " .. instancePath(it.inst)) syncAll() end) end end button(pBind, "สแกนรายการสำหรับช่องที่เลือก", doScan) button(pBind, "Auto-bind ช่องที่รู้จัก", function() autoBind(); syncAll() end) button(pBind, "ล้างการผูกช่องที่เลือก", function() State.bindings[selectedBindKey] = nil; notify("ล้างแล้ว"); syncAll() end) local bindStatus = label(pBind, "") local lc = card(pLog, "บันทึกและค่า config", "บันทึกเฉพาะการตั้งค่าและการผูกปุ่ม ไม่บันทึกให้ฟีเจอร์เปิดเองตอนโหลด. โหลดแล้วต้องเปิดใหม่เองเสมอ.") button(lc, "บันทึกค่า", function() local ok, err = saveConfig(); notify(ok and "บันทึกแล้ว" or ("บันทึกไม่ได้: " .. tostring(err))) end) button(lc, "โหลดค่า", function() local ok, err = loadConfig(); if ok then syncAll(); if State.config.antiAfk then setAntiAfk(true) end end; notify(ok and "โหลดแล้ว" or ("โหลดไม่ได้: " .. tostring(err))) end) button(lc, "คัดลอกลิงก์/ข้อมูลดีบัก", function() local text = "AGCC v" .. VERSION .. " executor=" .. identify() .. " place=" .. tostring(game.PlaceId) .. "\n" .. table.concat(State.logs, "\n") if CAP.setclipboard then setclipboard(text); notify("คัดลอกดีบักแล้ว") else notify("executor ไม่มี setclipboard") end end) local logBox = label(lc, "") State.refreshLogs = function() logBox.Text = table.concat(State.logs, "\n") end local QuickBar = make("Frame", { Size = UDim2.new(0, math.min(WIN_W, 360), 0, 42), Position = UDim2.new(0.5, -math.min(WIN_W, 360) / 2, 1, -58), BackgroundColor3 = COLORS.panel, BorderSizePixel = 0, Visible = false, ZIndex = 40 }, RootGui) corner(QuickBar, 10); stroke(QuickBar, COLORS.red, 1) local ql = list(QuickBar, 6); ql.FillDirection = Enum.FillDirection.Horizontal; ql.HorizontalAlignment = Enum.HorizontalAlignment.Center; ql.VerticalAlignment = Enum.VerticalAlignment.Center local function qbtn(text, fn, color) local b = make("TextButton", { Size = UDim2.fromOffset(76, 32), BackgroundColor3 = color or COLORS.redDark, Text = text, TextColor3 = COLORS.text, Font = FONT, TextSize = 13, BorderSizePixel = 0, ZIndex = 41 }, QuickBar) corner(b, 8); b.MouseButton1Click:Connect(function() safe(fn) end); return b end qbtn("เมนู", function() Window.Visible = not Window.Visible end) qbtn("STOP", function() stopAll("quickbar"); syncAll() end, COLORS.red) qbtn("โรล", function() if State.roll.active then stopRolling("quickbar") else startRolling() end; syncAll() end) qbtn("ขาย", function() State.config.autoSell = not State.config.autoSell; syncAll() end) local function dragify(handle, target, clampToScreen) local dragging, dragStart, startPos = false, nil, nil handle.InputBegan:Connect(function(input) if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then dragging = true; dragStart = input.Position; startPos = target.Position input.Changed:Connect(function() if input.UserInputState == Enum.UserInputState.End then dragging = false end end) end end) connect(UserInputService.InputChanged, function(input) if not dragging then return end if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then local delta = input.Position - dragStart local nx = startPos.X.Offset + delta.X local ny = startPos.Y.Offset + delta.Y if clampToScreen then local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(800, 600) nx = math.clamp(nx, 0, math.max(0, vp.X - target.AbsoluteSize.X)) ny = math.clamp(ny, 0, math.max(0, vp.Y - target.AbsoluteSize.Y)) end target.Position = UDim2.new(startPos.X.Scale, nx, startPos.Y.Scale, ny) end end) end dragify(Header, Window, false) dragify(ToggleButton, ToggleButton, true) ToggleButton.MouseButton1Click:Connect(function() Window.Visible = not Window.Visible end) CloseBtn.MouseButton1Click:Connect(function() Window.Visible = false end) StopBtn.MouseButton1Click:Connect(function() stopAll("ปุ่ม STOP"); syncAll() end) local function updateStatus() local g, csh = getCurrency() local rg, rt = readRollResult() homeStatus.Text = string.format("Executor: %s | Place: %s\nพล็อต: %s | ยืนยัน: %s\nGems: %s | Cash: %s\nBindings: %d | ESP objects: %d", identify(), tostring(game.PlaceId), State.plotPath or "ยังไม่เลือก", State.plotConfirmed and "yes" or "no", fmt(g), fmt(csh), (function() local n=0 for _ in pairs(State.bindings) do n+=1 end return n end)(), (function() local n=0 for _ in pairs(State.espObjects) do n+=1 end return n end)()) local tr = State.roll.tracker rollStatus.Text = string.format("สถานะ: %s | เหตุผลล่าสุด: %s\nเป้าหมาย: %s%s\nผลล่าสุด: %s / %s\nใช้ไปรอบนี้: gems %s, cash %s | โรลที่สังเกต: %d", State.roll.active and "กำลังโรล" or "หยุด", State.roll.stoppedReason ~= "" and State.roll.stoppedReason or "-", State.config.rollGradeTarget ~= "" and State.config.rollGradeTarget or "-", State.config.rollTraitTarget ~= "" and (" / " .. State.config.rollTraitTarget) or "", rg ~= "" and rg or "-", rt ~= "" and rt or "-", tr and fmt(tr.spentGems) or "0", tr and fmt(tr.spentCash) or "0", State.roll.changes) local bound = 0 for _, spec in ipairs(BindingSpecs) do if State.bindings[spec.key] then bound += 1 end end bindStatus.Text = "ผูกแล้ว " .. bound .. "/" .. #BindingSpecs .. " ช่อง\nช่องปัจจุบัน: " .. selectedBindKey .. " -> " .. (State.bindings[selectedBindKey] and State.bindings[selectedBindKey].path or "ยังไม่ได้ผูก") QuickBar.Visible = State.config.quickbar == true local sc = math.clamp(State.config.menuScale or 1, 0.7, 1.3) WinScale.Scale = sc end table.insert(syncWidgets, updateStatus) showPage("home") syncAll() local accum = { roll = 0, farm = 0, equip = 0, upgrade = 0, reward = 0, combat = 0, esp = 0, status = 0, rgb = 0 } local lastFrame = os.clock() connect(RunService.Heartbeat, function() if not State.running then return end local now = os.clock() local dt = now - lastFrame lastFrame = now if dt > 1 then dt = 1 end for k in pairs(accum) do accum[k] += dt end if State.config.rgb and gradient then if accum.rgb >= 0.05 then accum.rgb = 0 gradient.Rotation = (gradient.Rotation + 2) % 360 end else gradient.Rotation = 0 end if accum.roll >= math.max(0.2, State.config.rollPoll or 0.35) then accum.roll = 0 safe(rollTick) end if accum.farm >= math.max(1, State.config.sellInterval or 3) then accum.farm = 0 safe(farmTick) end if accum.equip >= math.max(5, State.config.equipInterval or 12) then accum.equip = 0 safe(equipTick) end if accum.upgrade >= math.max(2, State.config.upgradeInterval or 5) then accum.upgrade = 0 safe(upgradeTick) end if accum.reward >= math.max(3, State.config.rewardInterval or 8) then accum.reward = 0 safe(rewardTick) end if accum.combat >= math.max(2, State.config.combatInterval or 4) then accum.combat = 0 safe(function() combatTick("raid"); combatTick("tower") end) end if accum.esp >= 4 then accum.esp = 0 safe(espTick) end if accum.status >= 1 then accum.status = 0 safe(updateStatus) end end) local function unload() State.running = false pcall(function() stopAll("unload") end) pcall(function() setAntiAfk(false) end) pcall(clearEsp) for _, c in ipairs(Connections) do pcall(function() c:Disconnect() end) end pcall(function() RootGui:Destroy() end) if genv.AGCC_HUB_UNLOAD == unload then genv.AGCC_HUB_UNLOAD = nil end end genv.AGCC_HUB_UNLOAD = unload log("โหลด " .. TITLE .. " v" .. VERSION .. " สำเร็จ 